module.exports = {
    aiProviders: {
        ledger: {
            reservationTtlSeconds: 300,
            uncertainRetentionSeconds: 86400,
            expiryBatchSize: 100,
            maximumCompareAndSwapAttempts: 5,
            budget: {
                period: 'MONTH',
                scopeDimensions: [
                    'tenantCode',
                    'enterpriseCode',
                    'applicationCode',
                    'principalCode',
                    'profileCode',
                    'providerCode',
                    'modelCode'
                ],
                defaultMaximumTokens: 1000000,
                defaultMaximumCost: '100.00000000',
                currencyCode: 'USD'
            }
        }
    }
};

jobDetail: {
    internal: {
        module: 'aiProviders',
        method: 'POST',
        uri: '/internal/ai-ledger/repair/scan',
        body: {
            scheduleCode: 'ai-ledger-repair',
            dryRun: true
        }
    }
}
